INSERT INTO `knowledge_item` (id,knowledge_id,scene_item_id,scene_item_value,select_dict_tree_ids) VALUES (1807,213,11,'发给企业的东西，要经过企业确认',''),(1808,213,12,'发给企业的东西，要经过企业确认（明确收到企业在群里的确认），否则可能会没有按照要求准备。\n经验教训：南通某企业，我发评估资料群里，以为收到了，结果正式评估的时候根本没准备——微信会自动折叠很长的文字段，企业往往会忽略。参见配图',''),(1809,213,13,'',''),(1810,213,18,'企业确认',''),(1811,213,16,'2026-01-10 14:32:08',''),(1812,213,17,'卢剑伟',''),(1813,213,10,'','[\"17\",\"18\"]'),(1814,213,14,'/data/fdb2269e-f6ef-483a-bee2-57c2ca339c9c/222.png',''),(1815,213,15,'',''),(1816,214,11,'评估计划报备与变更要求',''),(1817,214,12,'每月5日填写在线表单（本月评估计划）；每月17日填写本月需要上会专家复核的企业信息。\n制度要求：评估机构应于每月5日前向CMMM®工作组秘书处报备当月计划，包括评估项目名称、受评估企业信息、评估时间、评估组组成等内容。\n如有特殊情况需调整的，应在项目实施前一周向CMMM®工作组秘书处书面报备调整后计划。\n未按照规定上报的评估项目，CMMM®工作组秘书处将不再受理该项目的合规性审查申请。',''),(1818,214,13,'',''),(1819,214,18,'每月填报',''),(1820,214,16,'2026-01-10 14:32:08',''),(1821,214,17,'卢剑伟',''),(1822,214,10,'','[\"17\",\"18\"]'),(1823,214,14,'',''),(1824,214,15,'',''),(1825,215,11,'情绪管控很重要',''),(1826,215,12,'非必要不对企业发火，可能会影响企业方的表达，最后我们反而不好收场',''),(1827,215,13,'',''),(1828,215,18,'情绪',''),(1829,215,16,'2026-01-10 14:32:08',''),(1830,215,17,'卢剑伟',''),(1831,215,14,'',''),(1832,215,15,'',''),(1833,215,10,'','[\"17\",\"18\"]'),(1834,216,11,'企业的行业代码要到C3MEP网站上-证书查询页面查查看，要一致',''),(1835,216,12,'一方面考虑企业自身注册公司时候的行业分类，另一方面要到C3mep网站上查询确认',''),(1836,216,13,'',''),(1837,216,18,'行业类别',''),(1838,216,16,'2026-01-10 14:32:08',''),(1839,216,17,'卢剑伟',''),(1840,216,10,'','[\"3\",\"4\"]'),(1841,216,14,'',''),(1842,216,15,'',''),(1843,217,11,'首末次会拍照要有屏幕、评估组、企业人员',''),(1844,217,12,'可能会出现传达来去，这个人就忘记这个要求了',''),(1845,217,13,'',''),(1846,217,18,'拍照',''),(1847,217,16,'2026-01-10 14:32:08',''),(1848,217,17,'卢剑伟',''),(1849,217,10,'','[\"17\",\"18\"]'),(1850,217,14,'',''),(1851,217,15,'',''),(1852,218,11,'弱项表述：不符合XX能力子域二级a）条款要求，该条款得分PI。',''),(1853,218,12,'不要漏掉“能力子域”，要和上面统一“二级a）”表述；不能漏掉“要求”二字；应写“得分”而不是“打分”。',''),(1854,218,13,'',''),(1855,218,18,'弱项',''),(1856,218,16,'2026-01-10 14:32:08',''),(1857,218,17,'卢剑伟',''),(1858,218,14,'',''),(1859,218,15,'',''),(1860,218,10,'','[\"17\",\"20\"]'),(1861,219,11,'弱项与整改方案撰写要求',''),(1862,219,12,'弱项跟踪表及方案，更多的是形式上的，要真搞个方案出来要好几个月的，所以目前评估完企业做的基本都是AI生成的，或者正好手头有相关资料拼凑。所以咱们也不要过于纠结这个跟踪表、方案的严谨性，纯粹是为了关闭弱项、赶专家复核用。\n有几个说明：\n1，附件可以是整改的方案，也可以是  企业自己整理的该弱项的  需求调研，或者是  调研的市面上类似产品的功能等，都可以。主要表名咱们企业已经开始着手去做弱项改善了。\n2，实施计划。不要求一年内必须完成，可以是很多年完成，但一定要有时间表。后期也不会来根据时间表找企业确认。因为任何项目在企业执行都可能会因为各种原因发生各种变更，所以大家也不用担心时间设定是否合理、是否一定要按期完成。\n3，官方要求：整改方案需明确建设目标、资源投入（人员与资金预算）及预计完成时限。',''),(1863,219,13,'',''),(1864,219,18,'弱项',''),(1865,219,16,'2026-01-10 14:32:08',''),(1866,219,17,'卢剑伟',''),(1867,219,14,'',''),(1868,219,15,'',''),(1869,219,10,'','[\"17\",\"20\"]'),(1870,220,11,'查与抽的写法注意',''),(1871,220,12,'1，一条证据写一个查/抽，不要查/抽里面再分1-2-3，均应分开写，如，查：XXX。查：YYY。抽：ZZZ。抽：AAA。等\n2，查与抽，要按条款写！如果条款要求是动态过程，那么，查与抽里面描述的就应该包含动态的内容。如：计划与调度2a讲的是自动生成主生产计划，那么查与抽里面至少应包含某个主计划生成的过程，而不仅仅是对某个已经生成的主计划的静态描述！',''),(1872,220,13,'',''),(1873,220,18,'评估记录表',''),(1874,220,16,'2026-01-10 14:32:08',''),(1875,220,17,'卢剑伟',''),(1876,220,14,'',''),(1877,220,15,'',''),(1878,220,10,'','[\"17\",\"20\"]'),(1879,221,11,'弱项跟踪表里面“整改措施的验证”复选框一定要打钩！',''),(1880,221,12,'无',''),(1881,221,13,'',''),(1882,221,18,'弱项',''),(1883,221,16,'2026-01-10 14:32:08',''),(1884,221,17,'卢剑伟',''),(1885,221,14,'',''),(1886,221,15,'',''),(1887,221,10,'','[\"17\",\"20\"]'),(1888,222,11,'评估报告的表格中“评估发起人”不要漏掉职务',''),(1889,222,12,'如：王巍（总经理）',''),(1890,222,13,'',''),(1891,222,18,'评估报告',''),(1892,222,16,'2026-01-10 14:32:08',''),(1893,222,17,'卢剑伟',''),(1894,222,14,'',''),(1895,222,15,'',''),(1896,222,10,'','[\"17\",\"20\"]'),(1897,223,11,'条款打分PI时，评估记录、弱项里面多少要写一点和标准靠得上的内容，否则就是NI了',''),(1898,223,12,'无',''),(1899,223,13,'',''),(1900,223,18,'评估记录表',''),(1901,223,16,'2026-01-10 14:32:08',''),(1902,223,17,'卢剑伟',''),(1903,223,10,'','[\"17\",\"20\"]'),(1904,223,14,'',''),(1905,223,15,'',''),(1906,224,11,'所有图表都应该清晰可见，不可出现文字交叉，如雷达图',''),(1907,224,12,'要站在专家复核的角度，看的是打印纸质稿，交叉就看不清',''),(1908,224,13,'',''),(1909,224,18,'评估报告',''),(1910,224,16,'2026-01-10 14:32:08',''),(1911,224,17,'卢剑伟',''),(1912,224,14,'',''),(1913,224,10,'','[\"17\",\"20\"]'),(1914,224,15,'',''),(1915,225,11,'查与抽一定要围绕标准条款',''),(1916,225,12,'查与抽一定要围绕标准条款\n如：人员技能2a）就要证明相关人员有相关能力。\n【20241121期专家复核会会议纪要】评估记录无法支撑评估结论。如组织战略中，未明确技术架构、资源投入的具体内容。\n【20240806期专家复核会会议纪要】详细评估记录中的举证证据和过程记录无法支撑打分结论。例如：P60设备管理3级a）仅举证了回流焊机的数据采集，就直接给出FI结论，预评估识别的关键设备如：锡膏印刷机、SPI监测机、贴片机、AOI检验机、自动涂覆机等均未举证。P53计划与调度3级b）仅举证了MES的工单管理功能，未说明基于有限产能算法开展详细作业计划制定的内容。',''),(1917,225,13,'',''),(1918,225,18,'评估记录表',''),(1919,225,16,'2026-01-10 14:32:08',''),(1920,225,17,'卢剑伟',''),(1921,225,14,'',''),(1922,225,10,'','[\"17\",\"18\"]'),(1923,225,15,'',''),(1924,226,11,'合影站位',''),(1925,226,12,'一般请企业评估发起人站中间，评估组长、组员、见习评估师按次序排列或分列在评估发起人两边',''),(1926,226,13,'',''),(1927,226,18,'发起人',''),(1928,226,16,'2026-01-10 14:32:08',''),(1929,226,17,'卢剑伟',''),(1930,226,14,'',''),(1931,226,15,'',''),(1932,226,10,'','[\"3\",\"6\"]'),(1933,227,11,'末次会后离场',''),(1934,227,12,'一般建议企业要送评估老师上车，而不是会议室门口；送的人最好是企业领导>部门领导>联系人',''),(1935,227,13,'',''),(1936,227,18,'礼节',''),(1937,227,16,'2026-01-10 14:32:08',''),(1938,227,17,'卢剑伟',''),(1939,227,14,'',''),(1940,227,15,'',''),(1941,227,10,'','[\"3\",\"6\"]'),(1942,228,11,'礼品专家费',''),(1943,228,12,'非必须。但一般建议安排随手礼，以示礼节，无所谓贵贱；如果企业智能化水平、配合度不太好，或者表示重视，建议专家费，给组长或者所有组员，建议不要低于1000/人，低的话不如不给，太难看。',''),(1944,228,13,'',''),(1945,228,18,'礼品、礼物',''),(1946,228,16,'2026-01-10 14:32:08',''),(1947,228,17,'卢剑伟',''),(1948,228,15,'',''),(1949,228,10,'','[\"3\",\"6\"]'),(1950,228,14,'',''),(1951,229,11,'安排接待',''),(1952,229,12,'一般建议在评估组进场前（预评估和正式评估）安排一次接待，以示重视；安排在企业内或者外部都可以；如果每天都是桌餐，不另外安排接待也可以。',''),(1953,229,13,'',''),(1954,229,18,'后勤',''),(1955,229,16,'2026-01-10 14:32:08',''),(1956,229,17,'卢剑伟',''),(1957,229,15,'',''),(1958,229,10,'','[\"3\",\"6\"]'),(1959,229,14,'',''),(1960,230,11,'餐饮安排与注意',''),(1961,230,12,'1，午餐和晚餐（如晚上加班）以便捷、干净为准，可以桌餐、点外卖或者外出就餐，但除非食堂环境、饮食标准还可以，否则不建议和企业员工一起在食堂用餐，特别是要排长队、伙食差的场景要规避。\n2，点餐时建议随口问一下老师是否有忌口（如不吃香菜、蒜、韭菜、猪肉等）。\n3，如果接待时间很晚，尽量不要干等。如：\n某三级评估第一天晚上，企业安排接待，但自身一直在开会到19点半以后，中途也一直说不知道要多久，评估组干等着。此时建议准备一些饼干等。',''),(1962,230,13,'',''),(1963,230,18,'后勤',''),(1964,230,16,'2026-05-08 15:39:28',''),(1965,230,17,'卢剑伟',''),(1966,230,14,'',''),(1967,230,15,'',''),(1968,230,10,'','[\"3\",\"6\"]'),(1969,231,11,'住宿要求',''),(1970,231,12,'如住宿由企业方解决，原则上干净、整洁就可以，但建议至少安排“亚朵、桔子”档次的连锁酒店，品质有保证，或者由评估老师自己订酒店（评估老师基本素质都有，不会去订五星级酒店）。之前遇到过企业合作酒店听起来高大上，实际入住体验很糟糕（地毯和桌子上都是烟头烫焦的痕迹、一股烟味），直接让评估组认为企业不重视，影响睡眠、心情等，最后影响审核过程。',''),(1971,231,13,'',''),(1972,231,18,'后勤',''),(1973,231,16,'2026-01-10 14:32:08',''),(1974,231,17,'卢剑伟',''),(1975,231,15,'',''),(1976,231,14,'',''),(1977,231,10,'','[\"3\",\"6\"]'),(1978,232,11,'会场布置',''),(1979,232,12,'建议会场布置热水壶、水果、小点心（如：饼干）、抽纸等，也可以征求老师意见是否要泡茶、点咖啡等。\n强烈建议：容易吃的水果。实践证明：高强度评估中间吃点甜的、凉的东西，会极大提升评估感受，进而使得评估过程更顺畅',''),(1980,232,13,'',''),(1981,232,18,'后勤、水果',''),(1982,232,16,'2026-01-10 14:32:08',''),(1983,232,17,'卢剑伟',''),(1984,232,10,'','[\"3\",\"6\"]'),(1985,232,14,'',''),(1986,232,15,'',''),(1987,233,11,'微信群引见',''),(1988,233,12,'1，原则：按照先客后主引见，即商务先给咨询方介绍企业方人员，再反过来；咨询方先给评估老师介绍企业方，再反过来。\n2，引见前，先和双方私聊一下，问问有没有自我介绍的文字，或者和对方确认下如此引见是否可以。\n3，话术举例：@aaa XXX公司副总 X总，@bbb XXX公司YY部 Y总……@ccc XX教授，本项目评估组组长，是工信部智能制造专家、CMMM主任评估师……',''),(1989,233,13,'',''),(1990,233,18,'话术',''),(1991,233,16,'2026-01-10 14:32:08',''),(1992,233,17,'卢剑伟',''),(1993,233,14,'',''),(1994,233,15,'',''),(1995,233,10,'','[\"3\",\"6\"]'),(1996,234,11,'评估范围涉及到的产品名称有何讲究？',''),(1997,234,12,'1，原则上应见名知意、没有歧义、符合常规认知。\n2，可以参考企业体系证书的范围、申报智能工厂/车间的名称。\n3，反面案例\n【案例1】\n原范围：精研科技，MIM零部件的生产\n合规意见：MIM标识的含义没有明确的范围界定，建议修改。MIM根据申请表的介绍，更像是一种特殊工艺。\n修正后：金属粉末注射成型（MIM）产品的生产\n【案例2】\n原范围：许昌烟机，烟草机械的设计、生产、销售、服务\n合规意见：评估范围烟草机械的设计、生产、销售、服务中烟草机械的范围太大\n修正后：滤棒成型、辅联物流类烟草机械设备的设计、生产、销售、服务\n【案例3】\n原范围：海发智能，水系统的生产\n合规意见：水系统有歧义，建议改为水处理XXX设备（没仔细问）\n修正后：未修改，补充材料说明了“水系统”的理由（合同、百度百科、体系证书）',''),(1998,234,13,'',''),(1999,234,18,'申请表',''),(2000,234,16,'2026-01-10 14:32:08',''),(2001,234,17,'卢剑伟',''),(2002,234,14,'',''),(2003,234,15,'',''),(2004,234,10,'','[\"11\",\"12\"]'),(2005,235,11,'能源管理3c、集成3c、数据3c之间的技术相关性',''),(2006,235,12,'能源管理3c中企业能源系统如是单机版无法直接为其他业务系统提供决策支撑，那么数据3c和集成3c必然都要扣分，至少不能FI。\n如：许昌烟机案例（能源3c是PI，集成3c为LI，数据3c原为FI后改为LI）。',''),(2007,235,13,'',''),(2008,235,18,'打分',''),(2009,235,16,'2026-01-10 14:32:08',''),(2010,235,17,'卢剑伟',''),(2011,235,14,'',''),(2012,235,10,'','[\"17\",\"20\"]'),(2013,235,15,'',''),(2014,236,11,'设备管理3a、数据3a之间的技术相关性',''),(2015,236,12,'设备管理3a）如果企业无法实现全部设备关键运行参数的实时采集，则数据3a）就不能满分。\n如：许昌烟机案例（设备管理3a是LI，数据3a原为FI后改为LI）。',''),(2016,236,13,'',''),(2017,236,18,'打分',''),(2018,236,16,'2026-01-10 14:32:08',''),(2019,236,17,'卢剑伟',''),(2020,236,14,'',''),(2021,236,15,'',''),(2022,236,10,'','[\"17\",\"20\"]'),(2023,237,11,'评估记录编制时有什么注意事项',''),(2024,237,12,'1，每个条款的每个字都要描述清楚，查和抽的内容要覆盖标准的每个字！\n2，一般每个知识点写一个查、一个抽。',''),(2025,237,13,'',''),(2026,237,18,'评估记录表',''),(2027,237,16,'2026-01-10 14:32:08',''),(2028,237,17,'卢剑伟',''),(2029,237,10,'','[\"17\",\"20\"]'),(2030,237,14,'',''),(2031,237,15,'',''),(2032,238,11,'合规审查一般检查哪些内容？',''),(2033,238,12,'1，完整性 \n1.1评估材料清单提交材料是否完整\n1.2评估记录填写是否完整\n1.3评估组是否按照要求完成组内人员评价\n1.4预评估问题是否关闭\n2，充分性\n2.1评估计划是否覆盖了评估申请范围的活动、场所\n2.2评估过程是否充分，评估记录的抽样是否覆盖了评估申请范围。\n3，有效性\n3.1评估组使用的评估工具和评估作业文档是否为有效版本\n3.2申请表、合同、评估计划、首末次会议签到表、评估报告的时间逻辑性是否一致\n3.3评估人员资质是否满足要求，提交材料中评估人员信息是否与平台信息一致\n3.4评估人日、评估组内成员配置是否与评估作业指导书要求一致\n3.5评估组成员是否满足公正性要求\n4，其他\n4.1是否存在错别字、文字表达等方面的低级错误\n5，技术审查（主任评估师负责）',''),(2034,238,13,'详见《CMMM®评估材料审查表》',''),(2035,238,18,'合规',''),(2036,238,16,'2026-01-10 14:32:08',''),(2037,238,17,'卢剑伟',''),(2038,238,14,'',''),(2039,238,15,'',''),(2040,238,10,'','[\"17\",\"20\"]'),(2041,239,11,'专家复核一般检查哪些内容？',''),(2042,239,12,'1，有效性\n1.1评估组的评估程序是否合规 \n1.2企业评估过程有不适用条款，不适用理由是否合理 \n1.3评估组对各能力子域的权重值调整是否合理 \n1.4预评估发现问题是否采取措施并关闭 \n1.5不适用能力子域理由说明与裁剪条款是否恰当 \n2，充分性\n2.1评估记录是否可追溯，记录内容是否为评估结论提供依据和证实材料\n（抽查至少2个能力子域的评估记录，验证记录内容是否充分、可追溯） \n2.2是否对企业识别的关键过程、活动或场所进行了有效评估，评估过程是否充分，评估记录的抽样是否覆盖了评估申请范围（根据评估报告XXX）\n3，准确性\n3.1评估组打分是否合理\n（抽查至少2个能力子域的评估过程记录，验证打分结果和记录内容是否匹配） \n3.2评估组给出的弱项或建议是否恰当 \n3.3评估弱项描述是否恰当、描述是否清晰、判据是否准确 \n常见问题：\n（1）评估弱项描述与能力子域条款要求缺乏对标性。（B）\n（2）评估弱项描述缺少实际事实证据说明，问题无法追溯。（B）\n（3）评估弱项描述超出标准内容的要求。（B）\n（4）评估弱项描述与其他能力子域内容存在矛盾（B）\n（5）评估弱项描述未考虑到企业的行业特征（B）\n（6）评估弱项描述与企业实际情况存在严重偏差（C）\" \n3.4评估结论是否有效。 ',''),(2043,239,13,'详见《CMMM®评估材料审查表》',''),(2044,239,18,'复核',''),(2045,239,16,'2026-01-10 14:32:08',''),(2046,239,17,'卢剑伟',''),(2047,239,10,'','[\"17\",\"20\"]'),(2048,239,14,'',''),(2049,239,15,'',''),(2050,240,11,'企业CMMM评估项目一般怎么推进？',''),(2051,240,12,'按照我们经验，为了避免中途可能出现的各种问题，一般建议按如下步骤进行：\n（1）给真正的企业高层（副总及以上）汇报，寻求高层支持，告知这不是项目申报！工信部专家组要驻场两次，每次多人多天，不可能作假，需要各部门全力支持！本项目一般由CIO/信息化主管担纲。\n（2）成立CMMM项目组，由高层任组长（评估发起人），各部门负责人（或其指定一名责任人）参加。\n（3）召开启动会，评估发起人要出席；会议内容：整体介绍CMMM项目，分子域进行条款解读、现状调研、布置任务（制作PPT、准备材料），并限期提交各子域PPT和文件清单。\n（4）对各部门提交的材料进行辅导，并让其修改后再次提交……周而复始，使得最终确认的材料覆盖标准、条理清晰。\n（5）可以安排一次模拟评估，按照正常评估过程走一遍，让责任人汇报各子域PPT接受质询等\n（6）撰写申请表、整体PPT\n（7）联系评估机构：提交申请表、文件清单、整体PPT、签订评估合同、打款\n（8）评估组长与企业联系：确认预评估时间\n（9）预评估（一般隔天晚上安排一次接待，末次会后送行老师）\n（10）正式评估（一般隔天晚上安排一次接待，末次会后送行老师）\n（11）等待公示与证书\n说明：如果企业条件达不到评估等级、需要智能化投入的，在（3）后应给企业出具整改建议，并与之讨论明确整改方案、跟进整改结果。',''),(2052,240,13,'',''),(2053,240,18,'咨询，推进，流程',''),(2054,240,16,'2026-01-10 14:32:08',''),(2055,240,17,'卢剑伟',''),(2056,240,15,'',''),(2057,240,10,'','[\"11\",\"12\"]'),(2058,240,14,'',''),(2059,241,11,'CMMM第三方评估的价值是什么？',''),(2060,241,12,'1.通过外部专家/外脑，对照国标诊断智能制造现状，客观了解企业当前智能制造的强项和弱项，找到改进思路和未来进行数字化投入的方向。\n2.通过第三方评估，作为智能制造类申报的加分项（智能工厂荣誉的事实要求）\n3.通过第三方评估，公正证明企业自身智能制造/数字化水平/投资建设成效\n4.通过第三方评估，建设并支撑纵向智能制造项目的验收\n5.通过第三方评估，领导层全面了解工厂业务流程/智能化情况\n6.通过第三方评估，验收企业内部智能化项目（效果：第三方评价>内部验收报告）\n7.通过第三方评估，成为行业第一家通过CMMM 三级的企业，股价拉升、质量与服务的信息化支撑与固化保障等\n8.通过第三方评估，成为集团内第一家通过CMMM 三级的企业\n9.通过第三方评估，获取所在地区的政策奖励',''),(2061,241,13,'',''),(2062,241,18,'第三方，价值，评估',''),(2063,241,16,'2026-01-10 14:32:08',''),(2064,241,17,'卢剑伟',''),(2065,241,15,'',''),(2066,241,14,'',''),(2067,241,10,'','[\"7\",\"8\"]'),(2068,242,11,'常规礼仪',''),(2069,242,12,'1，进电梯，挡住电梯门，请尊者先进；出电梯同样请尊者先出；\n2，坐车，5座，后右>后左>前右>后中；7座，中右>中左>前右>后排；如有单位性别可请其单独坐前右。',''),(2070,242,13,'',''),(2071,242,18,'礼仪',''),(2072,242,16,'2026-01-10 14:32:08',''),(2073,242,17,'卢剑伟',''),(2074,242,14,'',''),(2075,242,15,'',''),(2076,242,10,'','[\"3\",\"6\"]'),(2086,244,11,'年产值和CMMM等级是否有关系？',''),(2087,244,12,'年产值和CMMM等级是否有关系？\n答：严格来讲，没有直接关系！但一般产值越高，智能化程度越高！\n一般二级企业年产值都要过亿，至少5千万；三级企业都是5亿以上；四级的都是10亿以上。\n但也有例外，我们遇到过50亿的装配型企业，做二级还很勉强！',''),(2088,244,13,'',''),(2089,244,18,'产值，等级',''),(2090,244,16,'2026-01-10 14:32:08',''),(2091,244,17,'卢剑伟',''),(2092,244,15,'',''),(2093,244,10,'','[\"3\",\"5\"]'),(2094,244,14,'',''),(2095,245,11,'售前如何判断企业能做几级？',''),(2096,245,12,'售前判断一般三种，一是基于经验问问企业上一年末销售额、软件系统有哪些，然后发给我们；\n二是对照着我们提供的调研表/在线表格，10分钟左右做个简单调研，然后把材料发我给我们；\n三是安排一次线上会，由我们经验丰富的评估师对企业各部门做线上的简单调研（每个子域5分钟左右），总共1小时的样子，可以得知结论。\n前期可以简单点，但原则上建议签合同前应安排一次线上调研，以规避签合同的风险。',''),(2097,245,13,'',''),(2098,245,18,'售前，等级，判断',''),(2099,245,16,'2026-01-10 14:32:08',''),(2100,245,17,'卢剑伟',''),(2101,245,14,'',''),(2102,245,15,'',''),(2103,245,10,'','[\"7\",\"9\"]'),(2104,246,11,'联系企业售前判断网络会议的话术（三级）？',''),(2105,246,12,'可以选择1个生产全过程智能化程度最高的产品，对该产品的生产过程调研信息化的情况。\n涉及到：\n1，产品设计（可不评，三维设计工具、PLM/PDM使用、产品设计仿真）\n2，工艺设计（可不评，PLM/PDM使用、工艺设计仿真、产品设计与工艺设计协同）\n3，采购（采购计划编制与执行、供应商寻源和评价）\n4，计划与调度（主计划编制、详细作业计划编制、物料需求MRP、生产计划执行的监控与调整）\n5，生产作业（工艺文件下发、全工序生产过程中人机料的采集、生产过程追溯、产品质量知识库、数字化质量检测设备与系统）\n6，设备管理（设备点巡检维护保养的过程管理、设备联网与状态采集、OEE统计、设备故障知识库）\n7，安全环保（三废处理的信息采集，风险知识库、应急预案库）\n8，仓储配送（生产性原材料和成品的库位管理、WMS、按灯拣货等非人为目视识别的物料分拣、AGV等自动配送设备）\n9，能源管理（电表和气表的三级计量、能源管理系统、高能耗设备远程运行监控）\n10，物流（可不评，指成品到客户手上运输过程的管理；TMS、车辆实时定位、拆箱/拼箱）\n11，销售（销售计划编制过程、销售与采购/生产/物流通过软件系统联动的情况）\n12，客户服务（可不评，客户服务系统、在线客服、客服知识库）\n13，产品服务（可不评，是否智能化产品、产品服务系统）\n具体请看附件工作量表workbook的“设计、生产、物流、销售、服务”等标签页的二级、三级条款。每个子域10分钟左右。',''),(2106,246,13,'',''),(2107,246,18,'售前，判断，话术',''),(2108,246,16,'2026-01-10 14:32:08',''),(2109,246,17,'卢剑伟',''),(2110,246,15,'',''),(2111,246,10,'','[\"7\",\"9\"]'),(2112,246,14,'',''),(2113,247,11,'评估合同有什么要求？',''),(2114,247,12,'不能违反公正性，如：后付费（评估通过、公示、获证等），应在评估组进场前支付评估费用。',''),(2115,247,13,'',''),(2116,247,18,'评估合同，要求',''),(2117,247,16,'2026-01-10 14:32:08',''),(2118,247,17,'卢剑伟',''),(2119,247,15,'',''),(2120,247,14,'',''),(2121,247,10,'','[\"7\",\"10\"]'),(2122,248,11,'CMMM怎么选定各子域的汇报人？',''),(2123,248,12,'（1）汇报人的职责是向评估组介绍其所负责子域的各条款在企业是如何实施的。所以必须理解条款，且对企业该条款的做法很熟悉。\n（2）一般建议汇报人自己做PPT，这样可以按照他的思路汇报。\n（3）可以多人汇报，如A汇报PPT，BCD负责答辩。',''),(2124,248,13,'',''),(2125,248,18,'汇报人',''),(2126,248,16,'2026-01-10 14:32:08',''),(2127,248,17,'卢剑伟',''),(2128,248,15,'',''),(2129,248,10,'','[\"11\",\"12\"]'),(2130,248,14,'',''),(2131,249,11,'怎么做公司整体智能制造情况PPT（首次会用）？',''),(2132,249,12,'（一）、过程\n1，以申请表为纲展开（先写公司介绍、产品介绍、资质荣誉等，然后申请表里的顺序）。\n2，用于预评估和正式评估的首次会后，企业整体介绍智能制造成熟度，让专家评估前初步了解企业智能制造情况。\n3，用企业自己公司介绍的PPT模板做，以体现自己的特色。\n（二）、注意\n1，公司介绍要简化，围绕申请表展开\n2，重点是工艺流程、关键工序、质量控制点、在用的哪些信息系统等',''),(2133,249,13,'',''),(2134,249,18,'整体PPT',''),(2135,249,16,'2026-01-10 14:32:08',''),(2136,249,17,'卢剑伟',''),(2137,249,15,'',''),(2138,249,10,'','[\"11\",\"15\"]'),(2139,249,14,'',''),(2140,250,11,'各子域PPT怎么制作？怎么准备？',''),(2141,250,12,'（一）过程\n（1）PPT风格采用企业自己的企业介绍风格，封面写清楚子域名称、汇报人部门和姓名\n（2）正文按照CMMM的条款展开，一般先说低等级，再说高等级\n（3）评估二级的，需要准备一级和二级的；评估三级的，需要准备二级和三级；评估四级的，需要准备三级和四级。\n特别注意：任何子域的一级a）一定和二级a）、二级b）和三级b）之间有递进关系！除非你自己特别确定，否则必须要一级a）写一下，二级a）再写一下！\n（4）针对某个条款建议这样做PPT\nA，先原文复制标准条款，如：二级a)……\nB，如果该条款涉及到业务流程（如：工艺设计、生产作业、质量追溯等），应先用流程图的形式介绍该条款在企业是怎么推进的\nC，如果该条款涉及到数据统计（如：数字化设备比例、主要关键设备等），应提供明细和汇总\nD，并编辑文字对上述流程/图表，按照条款的关注点进行描述。描述时应定量，如采用RJ45、光纤的连接形式，通过XX品牌XXX型号的交换机，***实现了什么效果。\nE，接着附上证据的截图/贴图/视频，并按实际留档备查。\n（二）常见问题\n1，PPT表述和条款不符。如：人员技能二级b）和c）搞反了\n2，一级材料缺失！主要是各类制度规范文件。如：信息安全规范、产品设计流程、生产作业规范等。（要去看一级内容）\n3，证据链缺失！制度和记录要匹配！\n如：风险评估应有制度，并强化信息安全方面的记录，不能只写产线停工的风险！\n4，一定要真实预演！要完整表达！汇报人都不清楚企业情况（如信息安全制度、杀毒软件）。\n5，流程行业企业有遇到好几家，虽然信息化部门一直在，但因为不实际操作，IT人员讲的内容和实际业务人员不一样！！！',''),(2142,250,13,'',''),(2143,250,18,'子域，PPT',''),(2144,250,16,'2026-05-08 15:43:45',''),(2145,250,17,'卢剑伟',''),(2146,250,14,'',''),(2147,250,15,'',''),(2148,250,10,'','[\"11\",\"15\"]'),(2149,251,11,'四级评估的特殊要求有哪些？',''),(2150,251,12,'1，4级评估的企业，除人员、技术、资源和生产必评项外，至少选择产品设计、工艺设计、物流、销售、产品服务、客户服务中的1项以上。\n2，企业不能直接评估四级，原则上获得国家级智能工厂后或者获得CMMM三级一年后才能申请四级评估。',''),(2151,251,13,'',''),(2152,251,18,'四级，评估，要求',''),(2153,251,16,'2026-01-10 14:32:08',''),(2154,251,17,'卢剑伟',''),(2155,251,14,'',''),(2156,251,15,'',''),(2157,251,10,'','[\"7\",\"8\"]'),(2158,252,11,'维持性评估的流程是怎样？',''),(2159,252,12,'1，与基准性评估相比，维持性评估不需要预评估，但需要1个人天的文件审查（可线上）和正式评估（二级1人2天，三级2人2天，四级3人2天）；\n2，主任评估师带领评估组采用现场巡视、人员访谈、系统演示等方式开展评估工作，重点关注企业的改进提升成效，应收集适当的证据验证企业持续满足维持性评估的资格，至少覆盖以下内容：\n1) 检查验证上一周期提出的弱项及改进建议的落实和改进情况；\n2) 针对打分结果为“满足”（即结论标识为“S”）的能力子域采取抽样验证，验证企业是否持续满足要求，抽查比例不低于 1/3；\n3) 针对打分结果是“未满足”（即结论标识为“US”）的能力子域予以全部验证；\n4) 评估组应记录能够反映企业有序推进智能制造过程改进的信息。\n3，如果满足以下情况，企业持续满足原等级结果，通过维持性评估： \n1） 被抽查验证的能力子域（原结论“US”）中，至少有 1项实施了过程改进【从US变为S】，并取得阶段性成效；\n2） 被抽查验证的能力子域（原结论“S”）中，有效维持原等级要求，未出现系统性缺失。',''),(2160,252,13,'',''),(2161,252,18,'维持性评估，流程',''),(2162,252,16,'2026-01-10 14:32:08',''),(2163,252,17,'卢剑伟',''),(2164,252,10,'','[\"17\",\"21\"]'),(2165,252,15,'',''),(2166,252,14,'',''),(2176,254,11,'工作单位和社保单位要保持一致吗？',''),(2177,254,12,'CMMM培训证书在平台上注册要注意：工作单位和社保单位要一致，如不一致要写情况说明、双方盖章。',''),(2178,254,13,'',''),(2179,254,18,'注册，社保',''),(2180,254,16,'2026-01-10 14:32:08',''),(2181,254,17,'卢剑伟',''),(2182,254,14,'',''),(2183,254,10,'','[\"22\",\"24\"]'),(2184,254,15,'',''),(2185,255,11,'见习评估师的要求、条件、注册流程、资格保持',''),(2186,255,12,'见习评估师是指参加智能制造能力成熟度模型培训，且考试合格，在“智能制造能力成熟度评估管理平台”完成申请和注册，并在主任评估师的指导下参与 CMMM®评估工作的人员。见习评估师不能作为独立的评估人员。\n1 职责说明\n在主任评估师或评估师的指导下参与现场评估工作。\n2 教育和工作经历要求\n（1）大学本科及以上学历，具有 4 年相关领域工作经验；\n（2）具有大专学历的至少应具备 15 年全职工作经验。\n3 知识技能要求\n（1）参加成熟度模型培训并通过结业考试，获得培训合格证书；\n（2）了解工业企业设计、生产、物流、销售和服务领域专业知识和管理知识；\n（3）具备信息技术、自动化等智能制造相关领域知识。\n4 注册条件\n申请人应在获得智能制造能力成熟度模型培训合格证书 90 天内在 “ 智能制造能力成熟度评估管理平台 ”\n（www.c3mep.cn:8099/user/login ）完成申请和注册，审批通过后以见习评估师身份参与 CMMM®评估工作。\n5 资格保持\n获得见习评估师资格后，应在注册后 3 年内满足晋级条件，完成评估师晋级。',''),(2187,255,13,'',''),(2188,255,18,'见习评估师，要求',''),(2189,255,16,'2026-01-10 14:32:08',''),(2190,255,17,'卢剑伟',''),(2191,255,10,'','[\"22\",\"25\"]'),(2192,255,14,'',''),(2193,255,15,'',''),(2194,256,11,'正式评估师的要求、条件、注册流程、资格保持',''),(2195,256,12,'评估师是指满足本文件要求，经证实具有实施智能制造能力成熟度评估的个人素质和能力的人员，能够基于 GB/T 39116-2020《智能制造能力成熟度要求》和 GB/T 39117-2020《智能制造能力成熟度评估方法》对企业的智能制造能力成熟度做出准确判断。\n1 职责说明\n（1）作为正式评估组成员开展智能制造能力成熟度现场评估工作。\n2 教育和工作经历要求\n（1）大学本科及以上学历，应具有 4 年相关领域工作经验；\n（2）具有大专学历的至少应具备 15 年全职工作经验。\n3 知识技能要求\n（1）参加成熟度模型培训并通过结业考试，获得培训合格证书，全面掌握 GB/T 39116-2020《智能制造能力成熟度要求》和 GB/T 39117-2020《智能制造能力成熟度评估方法》，能正确表达和解释标准的条款及其含义，并应用于评估实践；\n（2）掌握评估过程方法、程序、工具和技巧，包括计算机辅助评估工具；\n（3）掌握工业企业的设计、生产、物流、销售和服务领域专业知识和管理知识；\n（4）具备信息技术、自动化等智能制造相关领域知识。\n4 注册条件\n申请人在 “ 智能制造能力成熟度评估管理平台 ”（www.c3mep.cn:8099/user/login）提交申请材料，申请人应在见习评估师注册通过时间 3 年内满足以下条件：\n（1）以见习评估师身份参与不少于 2 次及以上的现场评估工作，且主任评估师评价合格；\n（2）至少由主任评估师完成一次初始能力评价，且评价结论合格。\n5 注册程序\n（1）申请人按本文件要求，提交《CMMM®评估师注册申请表》以及相关证实性材料；\n（2）CMMM®评估工作组秘书处基于证实性材料对申请人进行综合能力评价，注册合格的人员将在“智能制造评估评价公共服务平台”（www.c3mep.cn）予以公示。\n6 资格保持\n获得评估师资格后，每年应以评估师身份至少参与 1 次智能制造能力成熟度评估工作，并在 3 年内取得相应积分，以保持评估师资格。未满足者降级为见习评估师。',''),(2196,256,13,'',''),(2197,256,18,'正式评估时，注册，保持，制度',''),(2198,256,16,'2026-01-10 14:32:08',''),(2199,256,17,'卢剑伟',''),(2200,256,14,'',''),(2201,256,15,'',''),(2202,256,10,'','[\"22\",\"26\"]'),(2203,257,11,'弱项整改跟踪表中，各项整改措施需设定明确的完成时间。',''),(2204,257,12,'无',''),(2205,257,13,'20251201期专家复核会会议纪要',''),(2206,257,18,'弱项',''),(2207,257,16,'2026-01-10 14:32:08',''),(2208,257,17,'卢剑伟',''),(2209,257,10,'','[\"17\",\"20\"]'),(2210,257,14,'',''),(2211,257,15,'',''),(2212,258,11,'专家复核驳回理由',''),(2213,258,12,'1、成都辰显光电有限公司—核验后再复核\n（1）企业销售收入增长缓慢，资产负债率呈上升趋势，建议评估机构和评估组配合CMMM工作组秘书处，核验企业25年财务数据。\n2、易客发（无锡）影像新材料有限公司—核验后再复核\n（1）建议评估机构和评估组配合CMMM工作组秘书处，对评估记录进行核验。\n3、厦门双瑞风电科技有限公司—整改后再复核\n（1）建议评估机构和评估组配合CMMM工作组秘书处，对评估记录进行核验。',''),(2214,258,13,'20251113期专家复核会会议纪要',''),(2215,258,18,'专家复核，驳回',''),(2216,258,16,'2026-01-10 14:32:08',''),(2217,258,17,'卢剑伟',''),(2218,258,15,'',''),(2219,258,10,'','[\"17\",\"18\"]'),(2220,258,14,'',''),(2221,259,11,'请确保申请表信息和评估报告信息一致。',''),(2222,259,12,'请确保申请表信息和评估报告信息一致。',''),(2223,259,13,'20250922期专家复核会会议纪要',''),(2224,259,18,'申请表，评估报告',''),(2225,259,16,'2026-01-10 14:32:08',''),(2226,259,17,'卢剑伟',''),(2227,259,10,'','[\"17\",\"20\"]'),(2228,259,14,'',''),(2229,259,15,'',''),(2230,260,11,'专家复核驳回理由',''),(2231,260,12,'整改后再复核\n1、苏州芯聚半导体有限公司—整改后再复核\n（1）企业智能制造能力建设的成效目前不显著，建议实现质量提升、成本降低、效益提升后再复核。\n（2）申请表和评估报告信息显示企业目前还处于新产品研发和量产验证阶段，请评估组再次评估确认。\n2、台山市精诚达电路有限公司—整改后再复核\n（1）企业现状未体现成熟度三级“集成”特征，在计划与调度、仓储配送、设备管理能力子域方面存在明显短板。\n（2）建议企业完成关键环节的弱项整改后，评估组再次进行评估确认。待评估组确认后，配合CMMM工作组秘书处就弱项整改实施情况等进行核验，并提交核验情况说明。\n3、广东海信电子有限公司—整改后再复核\n（1）请评估组重新确认评估范围，能力子域不适用理由。\n（2）建议企业完成关键环节的弱项整改后，评估组再次进行评估确认。评估组确认后，配合CMMM工作组秘书处就弱项整改实施情况等进行核验，并提交核验情况说明。',''),(2232,260,13,'20250922期专家复核会会议纪要',''),(2233,260,18,'专家复核，驳回',''),(2234,260,16,'2026-01-10 14:32:08',''),(2235,260,17,'卢剑伟',''),(2236,260,14,'',''),(2237,260,15,'',''),(2238,260,10,'','[\"17\",\"20\"]'),(2239,261,11,'务必准确填写评估地址所在的省、市、区（县）全称，请勿填写区域简称或直接引用企业注册地址。',''),(2240,261,12,'为确保评估地址的准确性，请务必准确填写评估地址所在的省、市、区（县）全称，请勿填写区域简称或直接引用企业注册地址。\n正确示例：广东省深圳市龙华区观湖街道观澜高新园区观清路1号\n错误示例：\n（1）深圳市龙华区观湖街道观澜高新园区观清路1号；\n（2）深圳市观湖街道观澜高新园区观清路1号；\n（3）成都高新区新园大道16号\n（4）苏州工业园区科智路1号中新科技工业坊二期E1、E2、D2、H栋厂房',''),(2241,261,13,'20250821期专家复核会会议纪要',''),(2242,261,18,'评估地址',''),(2243,261,16,'2026-01-10 14:32:08',''),(2244,261,17,'卢剑伟',''),(2245,261,10,'','[\"11\",\"15\"]'),(2246,261,15,'',''),(2247,261,14,'',''),(2248,262,11,'专家复核驳回理由',''),(2249,262,12,'1、成都苑东生物制药股份有限公司—整改后再复核\n（1）企业作为化学药品制剂生产企业，在生产数据采集和生产过程追溯的关键环节存在明显短板。\n（2）建议企业完成关键环节的弱项整改后，评估组再次进行评估确认。评估组确认后，配合CMMM工作组秘书处就弱项整改实施情况等进行核验，并提交核验情况说明。\n2、四川省钢构制造有限公司—核验后再复核\n（1）评估报告综述部分与数据、集成、生产作业、仓储配送能力子域打分及详细记录存在多处错误和逻辑矛盾。\n（2）建议评估机构和评估组配合CMMM工作组秘书处就详细评估记录和评估打分等进行核验，提交核验情况说明。\n3、贵州振华新材料有限公司—核验后再复核\n（1）企业智能制造能力建设的成效目前不显著。\n（2）建议评估机构和评估组配合CMMM工作组秘书处就企业实际经营状况、智能制造建设成效提升情况、弱项整改实施情况进行核验，并提交核验情况说明。\n4、贵州振华义龙新材料有限公司—核验后再复核\n（1）企业智能制造能力建设的成效目前不显著。\n（2）建议评估机构和评估组配合CMMM工作组秘书处就企业实际经营状况、智能制造建设成效提升情况、弱项整改实施情况进行核验，并提交核验情况说明。\n5、昕诺飞灯具（成都）有限公司—整改后再复核\n（1）企业现状未体现成熟度三级“集成”特征，在计划与调度、装备、能源管理、设备管理、工艺设计等能力子域方面存在明显短板。\n（2）建议企业完成关键环节的弱项整改后，评估组再次进行评估确认。待评估组确认后，配合CMMM工作组秘书处就弱项整改实施情况等进行核验，并提交核验情况说明。\n6、四川忠华智能科技有限公司—整改后再复核\n（1）企业现状未体现成熟度三级“集成”特征，在仓储配送、计划与调度、设备管理、能源管理等能力子域方面存在明显短板。\n（2）建议企业完成关键环节的弱项整改后，评估组再次进行评估确认。待评估组确认后，配合CMMM工作组秘书处就弱项整改实施情况等进行核验，并提交核验情况说明。',''),(2250,262,13,'20250821期专家复核会会议纪要',''),(2251,262,18,'专家复核',''),(2252,262,16,'2026-01-10 14:32:08',''),(2253,262,17,'卢剑伟',''),(2254,262,10,''